description:
Analiza esta función:

function check(input) {
  let key = [70,76,65,71,123,114,51,118,51,114,115,51,125];
  if (input.length !== key.length) return false;
  for (let i = 0; i < key.length; i++) {
    if (input.charCodeAt(i) !== key[i]) return false;
  }
  return true;
}

¿Qué string retorna true?

Analiza esta función de validación:

function validate(s) {
  if (s.length !== 16) return false;
  if (s.slice(0,5) !== 'FLAG{') return false;
  if (s[s.length-1] !== '}') return false;
  let inner = s.slice(5, -1);
  let sum = 0;
  for (let c of inner) sum += c.charCodeAt(0);
  return sum === 567 && inner.includes('m3d') && inner.startsWith('r3v');
}

¿Qué string pasa la validación?

Analiza este pseudocódigo en C:

void check(char *input) {
  char buffer[8];
  int authenticated = 0;
  strcpy(buffer, input);  // sin verificar longitud
  if (authenticated == 1) win();
}

La función win() imprime el flag. ¿Qué input de 12+ chars lo activa?
Memoria: [buffer(8 bytes)][authenticated(4 bytes)]
